-- AFTER DARK — schéma Supabase initial (PostgreSQL)
-- À exécuter dans Supabase > SQL Editor du projet ejmidupqavmgyowwlwqn.
-- Ne jamais mettre une clé service_role dans le navigateur.
create extension if not exists pgcrypto;

create table if not exists public.ad_couples (
  id uuid primary key default gen_random_uuid(),
  name text not null default 'Notre espace',
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
create table if not exists public.ad_members (
  couple_id uuid not null references public.ad_couples(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  nickname text not null default 'Partenaire',
  joined_at timestamptz not null default now(),
  primary key (couple_id,user_id),
  unique (user_id)
);
create table if not exists public.ad_invites (
  id uuid primary key default gen_random_uuid(),
  couple_id uuid not null references public.ad_couples(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null,
  used_at timestamptz,
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);
create table if not exists public.ad_rounds (
  id uuid primary key default gen_random_uuid(),
  couple_id uuid not null references public.ad_couples(id) on delete cascade,
  state jsonb not null default '{}'::jsonb,
  status text not null default 'active' check (status in ('active','revealed','finished')),
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists public.ad_answers (
  id uuid primary key default gen_random_uuid(),
  round_id uuid not null references public.ad_rounds(id) on delete cascade,
  couple_id uuid not null references public.ad_couples(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  card_id text not null,
  answer text not null check (answer in ('yes','no','maybe')),
  created_at timestamptz not null default now(),
  unique(round_id,user_id,card_id)
);
create index if not exists ad_rounds_couple_updated on public.ad_rounds(couple_id,updated_at desc);
create index if not exists ad_answers_round on public.ad_answers(round_id,card_id);

alter table public.ad_couples enable row level security;
alter table public.ad_members enable row level security;
alter table public.ad_invites enable row level security;
alter table public.ad_rounds enable row level security;
alter table public.ad_answers enable row level security;

-- Helper: current user belongs to a couple.
create or replace function public.ad_is_member(p_couple uuid)
returns boolean language sql stable security definer set search_path=public
as $$ select exists(select 1 from public.ad_members m where m.couple_id=p_couple and m.user_id=auth.uid()); $$;
revoke all on function public.ad_is_member(uuid) from public;
grant execute on function public.ad_is_member(uuid) to authenticated;

create policy "members read own couple" on public.ad_couples for select to authenticated
using (public.ad_is_member(id));
create policy "members read membership" on public.ad_members for select to authenticated
using (user_id=auth.uid() or public.ad_is_member(couple_id));
create policy "self update nickname" on public.ad_members for update to authenticated
using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "members read rounds" on public.ad_rounds for select to authenticated
using (public.ad_is_member(couple_id));
create policy "members create rounds" on public.ad_rounds for insert to authenticated
with check (public.ad_is_member(couple_id) and created_by=auth.uid());
create policy "members update rounds" on public.ad_rounds for update to authenticated
using (public.ad_is_member(couple_id)) with check (public.ad_is_member(couple_id));
-- Each player can only read/write their own answers. A reveal RPC is required to show both.
create policy "answer owner reads own" on public.ad_answers for select to authenticated
using (user_id=auth.uid() and public.ad_is_member(couple_id));
create policy "answer owner inserts own" on public.ad_answers for insert to authenticated
with check (user_id=auth.uid() and public.ad_is_member(couple_id));
create policy "answer owner updates own" on public.ad_answers for update to authenticated
using (user_id=auth.uid()) with check (user_id=auth.uid());

-- Create a private couple. The caller becomes member 1.
create or replace function public.ad_create_couple(p_nickname text default 'Partenaire')
returns uuid language plpgsql security definer set search_path=public
as $$
declare c uuid;
begin
  if auth.uid() is null then raise exception 'Authentification requise'; end if;
  if exists(select 1 from public.ad_members where user_id=auth.uid()) then raise exception 'Ce compte appartient déjà à un couple'; end if;
  return c;
end; $$;
revoke all on function public.ad_create_couple(text) from public;
grant execute on function public.ad_create_couple(text) to authenticated;

-- Generate a single-use invite. The raw token is returned only to its creator; only its hash is stored.
create or replace function public.ad_create_invite(p_couple uuid)
returns text language plpgsql security definer set search_path=public
as $$
declare raw_token text; h text;
begin
  if not public.ad_is_member(p_couple) then raise exception 'Accès refusé'; end if;
  if (select count(*) from public.ad_members where couple_id=p_couple)>=2 then raise exception 'Ce couple a déjà deux membres'; end if;
  raw_token:=encode(gen_random_bytes(24),'hex'); h:=encode(digest(raw_token,'sha256'),'hex');
  values(p_couple,h,now()+interval '24 hours',auth.uid());
  return raw_token;
end; $$;
revoke all on function public.ad_create_invite(uuid) from public;
grant execute on function public.ad_create_invite(uuid) to authenticated;

-- Join with the one-time token; exactly two members maximum.
create or replace function public.ad_join_invite(p_token text,p_nickname text default 'Partenaire')
returns uuid language plpgsql security definer set search_path=public
as $$
declare inv public.ad_invites%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentification requise'; end if;
  if exists(select 1 from public.ad_members where user_id=auth.uid()) then raise exception 'Ce compte appartient déjà à un couple'; end if;
  select * into inv from public.ad_invites where token_hash=encode(digest(p_token,'sha256'),'hex') and used_at is null and expires_at>now() for update;
  if not found then raise exception 'Invitation invalide ou expirée'; end if;
  if (select count(*) from public.ad_members where couple_id=inv.couple_id)>=2 then raise exception 'Ce couple est complet'; end if;
  update public.ad_invites set used_at=now() where id=inv.id;
  return inv.couple_id;
end; $$;
revoke all on function public.ad_join_invite(text,text) from public;
grant execute on function public.ad_join_invite(text,text) to authenticated;

-- Explicit shared reveal: returns answers only after both members answered the card.
create or replace function public.ad_reveal_card(p_round uuid,p_card_id text)
returns table(user_id uuid,answer text) language plpgsql security definer set search_path=public
as $$
declare c uuid; n int;
begin
  select r.couple_id into c from public.ad_rounds r where r.id=p_round;
  if c is null or not public.ad_is_member(c) then raise exception 'Accès refusé'; end if;
  select count(distinct a.user_id) into n from public.ad_answers a where a.round_id=p_round and a.card_id=p_card_id and a.couple_id=c;
  if n<2 then raise exception 'Réponses pas encore toutes déposées'; end if;
  return query select a.user_id,a.answer from public.ad_answers a where a.round_id=p_round and a.card_id=p_card_id and a.couple_id=c;
end; $$;
revoke all on function public.ad_reveal_card(uuid,text) from public;
grant execute on function public.ad_reveal_card(uuid,text) to authenticated;


-- Catalogue AFTER DARK v1 : cartes et récompenses Mythiques.
create table if not exists public.card_catalog (
  id text primary key,
  tier text not null check (tier in ('SOFT','HARD','SPICY','SPICY_EXTRÊME')),
  kind text not null check (kind in ('discovery','independent','realization')),
  theme_id text not null,
  payload jsonb not null,
  created_at timestamptz not null default now()
);
create table if not exists public.mythic_catalog (
  id text primary key,
  achievement_id text not null unique,
  payload jsonb not null,
  created_at timestamptz not null default now()
);


-- AFTER DARK — IMPORT COMPLET DU CATALOGUE (600 cartes + 25 Mythiques)
alter table public.card_catalog enable row level security;
alter table public.mythic_catalog enable row level security;
drop policy if exists "authenticated read card catalog" on public.card_catalog;
create policy "authenticated read card catalog" on public.card_catalog for select to authenticated using (true);
drop policy if exists "authenticated read mythic catalog" on public.mythic_catalog;
create policy "authenticated read mythic catalog" on public.mythic_catalog for select to authenticated using (true);
grant select on public.card_catalog, public.mythic_catalog to authenticated;

